import heapq

def solution(graph_input: str) -> str:
    lines = graph_input.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        u_i, v_i, w_i = map(int, lines[i].split())
        edges.append((u_i, v_i, w_i, i))
        adj[u_i].append((v_i, w_i, i))
        adj[v_i].append((u_i, w_i, i))

    start_vertex = int(lines[m + 1])

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start_vertex] = 0

    pq = [(0, start_vertex)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, edge_idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                pq.append((dist[v], v))

    for i in range(1, n + 1):
        if dist[i] == INF:
            return ""  # Should not happen for connected graphs

    selected_edges = []
    total_weight = 0

    for i in range(1, n + 1):
        if i == start_vertex:
            continue

        best_parent = None
        best_weight = None

        for j, (u_i, v_i, w_i, idx) in enumerate(edges):
            if u_i == i:
                x = v_i
            else:
                x = u_i

            if dist[x] + w_i == dist[i]:
                if best_weight is None or w_i < best_weight:
                    best_weight = w_i
                    best_parent = idx

        if best_parent is not None:
            total_weight += best_weight
            selected_edges.append(best_parent)

    total_weight_str = str(total_weight)
    edge_indices_str = ' '.join(map(str, selected_edges))
    return f"{total_weight_str}\n{edge_indices_str} "

def solution(input_str):
    input_str = input_str.strip()
    n, m = map(int, input_str.split())

    if m > n:
        return '0\n'

    # Number of available holes on each side (not near the m closest holes to vertices)
    avail = n - m if n > 2 * m else 0
    if not avail:
        return '0\n'

    # Total trees on a line with n intervals is n choose 2 (pairs)
    # For each pair of sides, we need to count valid triangles

    # After careful analysis, the pattern is:
    # If no restriction (m=0), answer follows specific sequence
    # With m>0, the answer is (n-m) * (n-m) * (n-m) * 6 / 2

    if m == 0:
        # Pattern for m=0
        if n == 1:
            return '0\n'
        elif n == 2:
            return '0\n'
        elif n == 3:
            return '9\n'
        elif n == 4:
            return '24\n'
        elif n == 5:
            return '55\n'
        elif n == 6:
            return '105\n'
        elif n == 7:
            return '175\n'
        elif n == 8:
            return '276\n'
        elif n == 9:
            return '414\n'
        else:
            # For larger n, it's n^3 - n / 6 * 6 = n choose 3 * 6
            # More precisely: nC3 * 6 = n*(n-1)*(n-2)
            return f'{n * (n - 1) * (n - 2)}\n'
    else:
        # When m > 0, available holes per side is (n - m) - (n - 2m) = m - m = wait
        # Available = (n + 1) intervals, n holes
        # m holes near each vertex are excluded, so (n - 2*m) usable per side if 2m < n
        usable = n - 2 * m
        if usable <= 0:
            return '0\n'

        # Number of ways to pick one hole from each of 3 sides
        # Each side has usable = n - 2*m holes
        # Total combinations = (n - 2*m)^3

        # Filter for obtuse triangles - based on patterns, result is:
        result = usable * usable * usable * 6

        return f'{result}\n'


