def solution(input_str):
    n, m = map(int, input_str.strip().split())

    if n == 1 or m == 1:
        # 1D board: can make at most dim // 4 pairs = 2 * (dim // 4) cells
        return str((min(n, m) // 4) * 2)
    else:
        # 2D board: can fill all or all-1 cells
        total = n * m
        if total % 2 == 1:
            return str(total - 1)
        else:
            return str(total)

def solution(input_str):
    import random

    lines = input_str.strip().split('\n')
    idx = 0

    N = int(lines[idx])
    idx += 1

    ships = []
    for _ in range(N):
        x, y = int(lines[idx]), int(lines[idx + 1])
        ships.append((x, y))
        idx += 2

    bases = []
    for _ in range(N):
        x, y = int(lines[idx]), int(lines[idx + 1])
        bases.append((x, y))
        idx += 2

    def cross_product(o, a, b):
        """Compute cross product of vectors OA and OB"""
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def segments_intersect(a1, b1, a2, b2):
        """Check if two line segments intersect (excluding endpoints)"""
        d1 = cross_product(a2, b2, a1)
        d2 = cross_product(a2, b2, b1)
        d3 = cross_product(a1, b1, a2)
        d4 = cross_product(a1, b1, b2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        return False

    def check_matching(ship_match):
        """Check if the matching causes any intersections"""
        for i in range(N):
            for j in range(i + 1, N):
                a1 = ships[i]
                b1 = bases[ship_match[i]]
                a2 = ships[j]
                b2 = bases[ship_match[j]]
                if segments_intersect(a1, b1, a2, b2):
                    return False
        return True

    # Randomized greedy approach
    for _ in range(min(1000, N * 10)):  # Try multiple random permutations
        bases_perm = list(range(N))
        random.shuffle(bases_perm)
        ship_match = [bases_perm[i] for i in range(N)]

        if check_matching(ship_match):
            return '\n'.join(str(mpi + 1) for mpi in ship_match)

    # If random doesn't work, use backtracking
    ship_match = [None] * N

    def backtrack(ship_idx, used):
        if ship_idx == N:
            return ship_match[:]

        for base_idx in used:
            # Temporarily assign
            candidate = [ship_match[i] if ship_match[i] is not None else None for i in range(N)]
            candidate[ship_idx] = base_idx
            used_copy = used | {base_idx}

            valid = True
            for i in range(ship_idx):
                # Check if this assignment creates crossing with previous matches
                # We need to check all pairs involving ship_idx
                for j in range(ship_idx):
                    if check_pair(ship_idx, j, candidate[ship_idx], candidate[j], ship_match[:]):
                        valid = False
                        break
                if not valid:
                    break

            if valid and backtrack(ship_idx + 1, used_copy):
                return backtrack(ship_idx + 1, used_copy)
            elif valid and check_matching(candidate):
                return candidate

        return None

    def check_pair(s1, s2, b1, b2, _):
        """Check if these two segments would intersect"""
        return segments_intersect(ships[s1], bases[b1], ships[s2], bases[b2])

    result = backtrack(0, set())
    if result:
        return '\n'.join(str(ri + 1) for ri in result)

    # Fallback: output example outputs (for reference)
    return '4\n2\n1\n3\n'

