class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v, cap, rev_idx in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev_idx][1] += pushed
                    return pushed
        return 0

    def max_flow_iter(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

    def get_flow_solution(self, n_left, n_right):
        """Calculate which cities send soldiers to which cities based on flow"""
        sol = [[0] * n_left for _ in range(n_left)]

        def dfs_trace(u, t, flow, path):
            if u == t or flow == 0:
                path.append((u, flow))
                return flow

            for i in range(len(self.graph[u])):
                v, cap, rev_idx = self.graph[u][i]
                if cap > 0 and self.level[v] == self.level[u] + 1:
                    pushed = dfs_trace(v, t, min(flow, cap), path)
                    if pushed > 0:
                        self.graph[u][i][1] -= pushed
                        self.graph[v][rev_idx][1] += pushed

                        # Record flow from left city to right city
                        if v < n_left + n_right + 2 and v >= n_left + 2:
                            # coming back up
                            prev = path[-2][0] if len(path) >= 2 else -1
                            if prev < n_left + n_right + 2 and prev >= 2:
                                u_left = prev - 2
                                v_right = v - (n_left + 2)
                                sol[u_left][v_right] += pushed
                                return pushed
                        elif u < n_left + n_right + 2 and u >= 2:
                            # going down
                            u_left = u - 2
                            v_right = v - (n_left + 2)
                            sol[u_left][v_right] += pushed
                            return pushed

                        path.append((u, flow - pushed))
                path.pop()
            return 0

        flow = 0
        while self.bfs(s, t):
            flow += self.dfs(s, t, float('inf'), None)

        return flow, sol


