                                dq.append(v)
                                rev3 = dinic.graph[v][len(dinic.graph[v]) - 1 - len([x for x in dinic.graph[0] if x[0] == v and x[2] == idx])]
                                if len(dinic.graph[v][v_idx]) > 0:
                                    result[i] += si
                                    # Add to matrix
