import math
import random

def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

def midpoint(p1, p2):
    return ((p1[0]+p2[0])/2, (p1[1]+p2[1])/2, (p1[2]+p2[2])/2)

def spheres_sphere(points, boundary):
    """Compute minimum enclosing sphere for points with given boundary points"""
    if not points:
        if not boundary:
            return None
        elif len(boundary) == 1:
            return (boundary[0], boundary[0], 0)
        elif len(boundary) == 2:
            c1, c2 = boundary[0], boundary[1]
            return (midpoint(c1, c2), dist(c1, c2))
        elif len(boundary) == 3:
            return solve_triangle_triplet(*boundary)
        elif len(boundary) == 4:
            return solve_tetrahedron(*boundary)
        return None

    p = points[0]
    ns, rad = spheres_sphere(points[1:], boundary + [p])

    if ns:
        if dist(ns[0], p) <= rad:
            return ns
        else:
            # Remove p from boundary and try again
            ns = spheres_sphere(points[1:], boundary)
            return ns

    return None

def solve_triangle_triplet(p1, p2, p3):
    """Find circumcenter of 3 points (on a plane or line)"""
    if len(p1) != 1 or len(p2) != 1 or len(p3) != 1:
        return None

    d1 = dist(p1, p2)
    d2 = dist(p2, p3)
    d3 = dist(p3, p1)

    # Handle collinear case (all points on a line)
    if abs(d3 - (d1 + d2)) < 1e-9 or abs(d1 - (d2 + d3)) < 1e-9 or abs(d2 - (d3 + d1)) < 1e-9:
        pts = [p1, p2, p3]
        pts.sort(key=lambda x: dist(x, pts[0]))
        return midpoint(pts[0], pts[2])

    # Solve for circumcenter of triangle
    A = [[2*(p1[0]-p2[0]), 2*(p1[1]-p2[1]), 2*(p1[2]-p2[2])],
         [2*(p1[0]-p3[0]), 2*(p1[1]-p3[1]), 2*(p1[2]-p3[2])]]
    b = [dist_d2(p1, p2) - dist_d2(p1, p2) / 2,
         dist_d2(p1, p3) - dist_d2(p1, p3) / 2] if False else []

    # Actually use formula-based approach
    center, r = circumcirc_of_3(p1, p2, p3)
    return center

def solve_tetrahedron(p1, p2, p3, p4):
    """Find circumcenter of 4 points"""
    center, r = circumcirc_of_4(p1, p2, p3, p4)
    if center is None:
        # Fallback to sphere through 3 points
        return solve_triangle_triplet(*p1[:3])
    return center

def dist_d2(p1, p2):
    return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

def circumcirc_of_3(p1, p2, p3):
    """Circumcenter of triangle in 3D"""
    if p1[0] - p2[0] == 0 and p1[1] - p2[1] == 0:
        return ((p1[0] + p2[0])/2, (p1[1] + p2[1])/2, p2[2])

    if abs(p3[0] - p1[0]) < 1e-9 and abs(p3[1] - p1[1]) < 1e-9:
        return midpoint(p1, p3), 0

    x1, y1, z1 = p1
    x2, y2, z2 = p2
    x3, y3, z3 = p3

    D = 2 * (x1*(y2-z3) + x2*(y3-z1) + x3*(y1-z2))
    if abs(D) < 1e-10:
        # Collinear
        pts = [p1, p2, p3]
        pts.sort(key=lambda x: dist(x, pts[0]))
        return midpoint(pts[0], pts[2]), dist(pts[0], pts[2]) / 2

    Ux = ((x1**2+y1**2+z1**2)*(y2-z3) + (x2**2+y2**2+z2**2)*(y3-z1) + (x3**2+y3**2+z3**2)*(y1-z2))
    Uy = ((x1**2+y1**2+z1**2)*(z2-x3) + (x2**2+y2**2+z2**2)*(z3-x1) + (x3**2+y3**2+z3**2)*(z1-x2))
    Uz = ((x1**2+y1**2+z1**2)*(x2-y3) + (x2**2+y2**2+z2**2)*(x3-y1) + (x3**2+y3**2+z3**2)*(x1-y2))

    center = (Ux/D, Uy/D, Uz/D)
    return (center, dist(center, p1))

def circumcirc_of_4(p1, p2, p3, p4):
    """Circumcenter of tetrahedron"""
    x1, y1, z1 = p1
    x2, y2, z2 = p2
    x3, y3, z3 = p3
    x4, y4, z4 = p4

    D = 0.0
    D1 = 0.0
    D2 = 0.0
    D3 = 0.0
    D4 = 0.0

    bc_x3_y1_z1 = y2*z3 - z2*y3
    bc_x3_y2_z2 = y3*z1 - z3*y1
    bc_x3_y3_z3 = y1*z2 - z1*y2

    bc_x4_y1_z1 = y4*z3 - z4*y3
    bc_x4_y2_z2 = y4*z1 - z4*y1
    bc_x4_y3_z3 = y1*z4 - z1*y4

    bc_x1_y3_z1 = y3*z4 - z3*y4
    bc_x1_y4_z4 = y4*z2 - z4*y2
    bc_x1_y2_z2 = y2*z4 - z2*y4

    bc_x2_y3_z3 = y3*z1 - z3*y1
    bc_x2_y4_z4 = y4*z2 - z4*y2
    bc_x2_y1_z1 = y1*z2 - z1*y2

    D += bc_x3_y1_z1 - bc_x3_y2_z2 - bc_x4_y1_z1 + bc_x4_y2_z2 + bc_x2_y3_z3 - bc_x2_y4_z4
    D1 += bc_x3_y1_z3 - bc_x3_y2_z4 - bc_x4_y1_z3 + bc_x4_y2_z3 + bc_x1_y3_z3
    D2 += bc_x3_y2_z1 - bc_x3_y3_z4 + bc_x4_y2_z1 - bc_x4_y3_z1 + bc_x1_y3_z3
    D3 += bc_x3_y3_z1 + bc_x4_y3_z2 - bc_x4_y3_z1 - bc_x3_y4_z2 - bc_x1_y3_z2

    D = 2.0 * D
    D1 = bc_x1_y3_z1 - bc_x1_y4_z4 + bc_x2_y3_z3 - bc_x2_y4_z4 + D1 - bc_x3_y4_z2 - bc_x3_y1_z4
    D2 = bc_x1_y3_z3 - bc_x1_y4_z4 + bc_x2_y3_z3 - bc_x2_y4_z4 + D2 - bc_x3_y4_z2 - bc_x3_y1_z4
    D3 = bc_x1_y4_z4 - bc_x1_y3_z3 + bc_x2_y4_z4 - bc_x2_y3_z3 + D3 - bc_x3_y4_z2 - bc_x3_y1_z4

    if abs(D) < 1e-10:
        # Degenerate case
        center = midpoint(p1, p4)
        return (center, dist_d2(center, p1))

    X = D1/D, D2/D, D3/D
    return tuple(X), dist(X, p1)

def min_enclosing_sphere(points):
    """Welzl-like recursive algorithm for minimum enclosing sphere"""
    points = list(points)
    random.shuffle(points)

    def welzl(points, boundary):
        if not points or len(boundary) == 4:
            if not boundary:
                return (points[0], 0) if points else None
            if len(boundary) == 1:
                return (boundary[0], 0), 0
            elif len(boundary) == 2:
                return midpoint(boundary[0], boundary[1]), dist(boundary[0], boundary[1])
            elif len(boundary) == 3:
                return circumcirc_of_3(boundary[0], boundary[1], boundary[2]), dist(boundary[0], boundary[1])
            else:
                return circumcirc_of_4(boundary[0], boundary[1], boundary[2], boundary[3]), dist(boundary[0], boundary[1])

        p = points[0]
        ns, rad = welzl(points[1:], boundary)

        if ns:
            if dist(ns[0], p) <= rad + 1e-9:
                return ns
            else:
                ns = welzl(points[1:], boundary + [p])
                return ns

        return None

    center, radius = welzl(points, [])
    if center is None:
        if len(points) == 1:
            return (points[0][0], points[0][1], points[0][2])
        else:
            return (0, 0, 0)
    return (center[0], center[1], center[2])

