def solution(s):
    def is_gp(arr):
        n = len(arr)
        if n <= 1:
            return True

        # All zeros is a GP
        if all(x == 0 for x in arr):
            return True

        # If first element is 0 but not all are 0, check carefully
        if arr[0] == 0:
            return False

        # For GP: arr[i] / arr[i-1] should be constant for all i
        # Use cross-multiplication: arr[i-1] * arr[i+1] == arr[i] * arr[i]
        # First compute the required ratio using first two elements
        # arr[1] / arr[0] = r, so arr[i] = arr[0] * r^(i)
        # We check: arr[i+1] * arr[0] == arr[i] * arr[1]
        for i in range(1, n - 1):
            if arr[i] == 0:
                # If arr[i] is 0, arr[i+1] must also be 0
                if arr[i + 1] != 0:
                    return False
                continue
            # Using cross-multiplication to avoid floating point issues
            if arr[i + 1] * arr[0] != arr[i] * arr[1]:
                return False

        return True

    # Parse input
    lines = s.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Check if already GP
    if is_gp(arr):
        return "0\n"

    # Try removing each element
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return "1\n"

    return "2\n"

