def solution(s):
    import sys
    sys.setrecursionlimit(200000)

    lines = s.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for line in lines[1:]:
        parts = line.split()
        if parts[0] == '1':
            events.append(1)  # type 1
        else:
            events.append((2, parts[1]))  # type 2

    # Split into segments based on type 1 events
    segments = []  # Each segment is a set of friend names
    current_segment = set()

    for event in events:
        if event == 1:
            if current_segment:
                segments.append(current_segment)
                current_segment = set()
        else:
            current_segment.add(event[1])

    if current_segment:
        segments.append(current_segment)

    # Handle empty case
    if not segments:
        return '0'

    # Collect all unique friend names and map to indices
    friends = set()
    for seg in segments:
        friends.update(seg)

    friend_list = sorted(friends)
    friend_to_idx = {f: i for i, f in enumerate(friend_list)}
    num_friends = len(friend_list)

    if num_friends == 0:
        return '0'

    # Build conflict graph: two friends conflict if they appear in the same segment
    # Conflict means they cannot both be happy (since handle can only be one name at a time per segment)
    conflict = [[False] * num_friends for _ in range(num_friends)]

    for seg in segments:
        seg_indices = [friend_to_idx[f] for f in seg]
        for i in range(len(seg_indices)):
            for j in range(i + 1, len(seg_indices)):
                conflict[seg_indices[i]][seg_indices[j]] = True
                conflict[seg_indices[j]][seg_indices[i]] = True

    # Solve maximum independent set using backtracking with pruning
    result = []

    def backtrack(idx, count, selected):
        nonlocal result

        # Upper bound pruning: count + remaining friends <= current result
        if count + (num_friends - idx) <= len(result):
            return

        # If we've placed all friends, update result
        if idx == num_friends:
            result.append(count)
            return

        # Try including friend idx (if compatible with already selected)
        can_include = True
        for already in selected:
            if conflict[already][idx]:
                can_include = False
                break

        if can_include:
            selected.append(idx)
            backtrack(idx + 1, count + 1, selected)
            selected.pop()

        # Try excluding friend idx
        backtrack(idx + 1, count, selected)

    backtrack(0, 0, [])

    return str(len(result))

def solution(input_data):
    from collections import deque

    lines = input_data.strip().split('\n')
    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    special_pairs = []
    for i in range(k):
        x, y = map(int, lines[2 + i].split())
        special_pairs.append((x, y))

    # Build prerequisite graph (p[i] -> i means p[i] must come before i)
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        pre = p[i - 1]
        if pre != 0:
            adj[pre].append(i)
            in_degree[i] += 1

    # Topological sort
    ans = []
    q = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            q.append(i)

    while q:
        u = q.popleft()
        ans.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Check if all nodes were included (no cycle)
    if len(ans) != n:
        return "0"

    # Map position of each node for fast lookup
    pos = [0] * (n + 1)
    for i, node in enumerate(ans):
        pos[node] = i

    # Verify special pairs - x must be immediately before y
    for x, y in special_pairs:
        if pos[x] + 1 != pos[y]:
            return "0"

    # Verify all prerequisites are satisfied
    for i in range(1, n + 1):
        pre = p[i - 1]
        if pre != 0 and pos[pre] > pos[i]:
            return "0"

    return " ".join(map(str, ans))

