    def get_grundy(x, k_val):
        # Precompute a few values or compute on demand
        # For k even: special pattern
        k_even = k_val % 2 == 0

        # Compute Grundy on demand
        memo = {0: 0}

        def compute_g(v):
            if v in memo:
                return memo[v]

            # Remove one cow
            SG_vals = {compute_g(v - 1)}

            # If v is even, can split
            if v % 2 == 0:
                half = v // 2
                if k_even:
                    split_g = 0
                else:
                    split_g = compute_g(half)
                SG_vals.add(split_g)

            # Compute mex
            mex = 0
            while mex in SG_vals:
                mex += 1

            memo[v] = mex
            return mex

        return compute_g(x)

    # Compute Grundy numbers using memoization for efficiency
    memo = {0: 0}

    def get_grundy_cached(x):
        if x in memo:
            return memo[x]

        k_even = k % 2 == 0

        # All reachable Grundy numbers from x
        SG_vals = {get_grundy_cached(x - 1)}

        if x % 2 == 0:
            half = x // 2
            if k_even:
                SG_vals.add(0)
            else:
                SG_vals.add(get_grundy_cached(half))

        # Compute mex
        mex = 0
        while mex in SG_vals:
            mex += 1

        memo[x] = mex
        return mex

    # Compute XOR sum of all piles
    xor_sum = 0
    for pile in piles:
        xor_sum ^= get_grundy_cached(pile)

