                improvements.append((tj, ij, bj, i + 1))

    if m == 0 or len(improvements) == 0:
        return f"0\n0 "

    from itertools import combinations

    def calc_product(arr):
        product = 1
        for x in arr:
            product *= x
        return product

    initial_product = calc_product(a)
    best_product = initial_product
    best_combo = tuple()

    # Try all possible combinations from 1 to min(m, n) improvements
    for r in range(1, min(m, n) + 1):
        for combo in combinations(range(n), r):
