import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    xp, yp, vp = map(int, lines[0].split())
    x, y, v, r = map(int, lines[1].split())

    # Persephone's orbit radius
    R = math.sqrt(xp*xp + yp*yp)

    # Initial angle
    angle0 = math.atan2(yp, xp)

    # Check if already at same position
    if math.sqrt((x - xp)**2 + **(y - yp)2) < 1e-15:
        return "0.000000000\n"

    def pos(t):
        # Persephone moves counter-clockwise with angular velocity vp/R
        angle = angle0 + vp * t / R
        return R * math.cos(angle), R * math.sin(angle)

    def min_dist_to_origin(x1, y1, x2, y2):
        """Minimum distance from origin to segment from (x1,y1) to (x2,y2)"""
        dx, dy = x2 - x1, y2 - y1
        L2 = dx*dx + dy*dy
        L = math.sqrt(L2)

        if L < 1e-15:
            # Point (degenerate segment)
            return math.sqrt(x1*x1 + y1*y1)

        # Perpendicular distance from origin to line
        h = abs(x1*dy - y1*dx) / L

        # Check if projection falls within segment
        dot = x1*dx + y1*dy
        if dot <= 0:
            return math.sqrt(x1*x1 + y1*y1)
        if dot >= L2:
            return math.sqrt(x2*x2 + y2*y2)

        return h

    # Binary search on time
    lo, hi = 0.0, 1e9
    for _ in range(100):
        mid = (lo + hi) / 2
        tx, ty = pos(mid)

        dist = min_dist_to_origin(x, y, tx, ty)
        if dist > r:
            lo = mid
        else:
            hi = mid

    return f"{hi:.10f}\n"

import math

def solution(input_str):
    """
    Count the number of primes in range [l, r] that can be represented as sum of two squares.
    According to Fermat's theorem on sums of two squares, a prime p can be written as sum of two squares
    iff p = 2 or p ≡ 1 (mod 4).
    """
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0"

    # Generate base primes up to sqrt(r) using sieve
    sqrt_r = int(math.isqrt(r))

    is_prime_small = [True] * (sqrt_r + 1)
    if sqrt_r >= 0:
        is_prime_small[0] = False
    if sqrt_r >= 1:
        is_prime_small[1] = False

    base_primes = []
    for i in range(2, sqrt_r + 1):
        if is_prime_small[i]:
            base_primes.append(i)
            start = i * i
            while start <= sqrt_r:
                is_prime_small[start] = False
                start += i

    # Segment [l, r]
    seg_len = r - l + 1
    is_prime = [True] * seg_len

    # Mark composites in segment
    for p in base_primes:
        if p * p > r:
            break
        # First multiple of p >= l
        start = max(p * p, (l + p - 1) // p * p)
        for i in range(start, r + 1, p):
            is_prime[i - l] = False

    # Handle special case where l itself is 2
    if l == 2 and is_prime[0]:
        pass

    # Count primes that are 2 or 1 (mod 4)
    count = 0
    for i in range(seg_len):
        if is_prime[i]:
            num = l + i
            if num == 2 or num % 4 == 1:
                count += 1

    return str(count)

