def calc_S_range_sum(n, d, m, i):
    """Calculate Σ_{x=m}^{i} len(str(x)) * (n - x + 1)"""
    if m > i:
        return 0

    count = i - m + 1
    sum_x = count * (m + i) // 2
    return d * (count * (n + 1) - sum_x)

def calc_S_range(n, d, m):
    """Calculate contribution from d-digit numbers up to min(n, m*10-1)"""
    end = min(n, m * 10 - 1)
    return calc_S_range_sum(n, d, m, end)

def calc_S(n):
    """Calculate S(n) = Σ_{i=1}^{n} L(i), where L(i) is total digits in "1...i""""
    if n <= 0:
        return 0

    total = 0
    d, m = 1, 1  # m = 10^(d-1), first number with d digits

    while m <= n:
        total += calc_S_range(n, d, m)
        m *= 10
        d += 1

    return total

def solve_query(k):
    # Binary search for the block n where S(n) >= k
    low, high = 1, 2000000000  # S(2e9) is much larger than 10^18
    n = high

    while low <= high:
        mid = (low + high) // 2
        if calc_S(mid) >= k:
            n = mid
            high = mid - 1
        else:
            low = mid + 1

    # Find position within block n
    pos_in_block = k - calc_S(n - 1)

    # Find which number in 1,2,3,...,n contains this position
    number = 1
    offset = 0
    while number <= n and offset + len(str(number)) < pos_in_block:
        offset += len(str(number))
        number += 1

    # Extract the digit
    remaining = pos_in_block - offset
    digit = str(number)[remaining - 1]
    return digit

