        if not t:
            # Query "d->" means d transforms to empty string
            digit_values[d] = {'val': 0, 'len': 0}
        else:
            # Query "d->t" where t is non-empty
            # d now transforms to the concatenated result of what each char in t becomes
            new_val = 0
            new_len = 0
            for ch in t:
                if ch in digit_values:
                    val = digit_values[ch]['val']
                    ln = digit_values[ch]['len']
                    # Concatenate: new_val = old_val * 10^ln + new_char_val (mod MOD)
