        try:
            a, b = map(int, line.split())
            if a < 1 or b < 1 or a == b:
                continue
            adj[a].append(b)
            adj[b].append(a)
            vertices.add(a)
            vertices.add(b)
        except:
            continue

    if len(vertices) != num_vertices or len(adj) != num_vertices:
        return "0\n"

    # BFS to build tree structure
    sorted_vertices = sorted(vertices)
    start = min(sorted_vertices)

    depth = {start: 0}
    parent = {start: -1}
    queue = deque([start])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in depth:
                depth[v] = depth[u] + 1
                parent[v] = u
                queue.append(v)

    if len(depth) != num_vertices:
        return "0\n"

    # Find all nodes that could be the parent of removed vertex
    candidates = []
    for u in vertices:
        # Node u could be parent if it has children
        has_children = any(parent[v] == u for v in depth if v != start)
        if has_children:
            candidates.append(u)

    if not candidates:
        # Include root
        candidates.append(start)

    candidates = sorted(list(set(candidates)))

    result = f"{len(candidates)}\n" + " ".join(map(str, candidates))
    if candidates:
        result += "\n"

    return result if result else "0\n"

