    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)

    # BFS from each node to compute distances to all other nodes
    dist = [[-1] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = deque([start])
        visited = [False] * (n + 1)
        visited[start] = True

        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1

            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Precompute top 2 candidates for best source and best destination
    # max_to[j] = list of up to 2 pairs (distance, i) where i is NOT j, sorted by distance desc
    max_to = [[] for _ in range(n + 1)]
    for j in range(1, n + 1):
        candidates = []
        for i in range(1, n + 1):
            if i != j and dist[i][j] != -1:
                candidates.append((dist[i][j], i))
        candidates.sort(key=lambda x: x[0], reverse=True)
        for d, i in candidates[:2]:
            max_to[j].append((d, i))

    # max_from[k] = list of up to 2 pairs (distance, l) where l is NOT k, sorted by distance desc
    max_from = [[] for _ in range(n + 1)]
    for k in range(1, n + 1):
        candidates = []
        for l in range(1, n + 1):
            if l != k and dist[k][l] != -1:
                candidates.append((dist[k][l], l))
        candidates.sort(key=lambda x: x[0], reverse=True)
        for d, l in candidates[:2]:
            max_from[k].append((d, i))

    best_total = -1
    best_cities = (1, 2, 3, 4)

    # Iterate over all pairs (j, k) as the middle two cities
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if j == k:
                continue
            if dist[j][k] == -1:
                continue

            # Find best i (not j, not k)
            for d, i in max_to[j]:
                if i != j and i != k:
                    break

            # Find best l (not i, not j, not k)
            for d, l in max_from[k]:
                if l != i and l != j and l != k:
                    break

            if dist[i][j] == -1 or dist[k][l] == -1:
                continue

            total = dist[i][j] + dist[j][k] + dist[k][l]
            if total > best_total:
                best_total = total
                best_cities = (i, j, k, l)

    return " ".join(map(str, best_cities))

