    end = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                end = (r, c)
                break
        if end:
            break

    # Standard directions (without any swaps)
    standard_dirs = {
        'U': (0, -1),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # Try all possible swap configurations
    configs = [
        (0, 0),  # no swaps
        (1, 0),  # L↔R swapped
        (0, 1),  # U↔D swapped
        (1, 1)   # both swapped
    ]

    from collections import deque

    for lr_swap, ud_swap in configs:
        # Build the direction mapping based on current swap assumption
        dir_map = {}
        for btn, (dr, dc) in standard_dirs.items():
            if btn == 'L' and lr_swap:
                dir_map[btn] = (0, 1)  # L moves right
            elif btn == 'R' and lr_swap:
                dir_map[btn] = (0, -1)  # R moves left
            elif btn == 'U' and ud_swap:
                dir_map[btn] = (1, 0)  # U moves down
            elif btn == 'D' and ud_swap:
                dir_map[btn] = (0, -1)  # D moves up
            else:
                dir_map[btn] = (dr, dc)

        # BFS to find path
        visited = set()
        queue = deque()
        queue.append((0, 0, ''))  # (row, col, path)
        visited.add((0, 0))

        found_path = []

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == end:
                found_path = path
                break

            # Try all directions
            for btn, (dr, dc) in dir_map.items():
                nr, nc = r + dr, c + dc

                # Check bounds
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] in ['.', 'F'] and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc, path + btn))

        if found_path:
            # Convert to string format with newlines
            result = '\n'.join(found_path) + '\n'
            return result

    return ''


