    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    # DFS traversal with cycle detection
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)

    stack = [1]
    visited[1] = True
    found_cycle = False
    cycle_nodes = []

    while stack:
        u = stack.pop()
        depth[u] = depth[parent[u]] + 1 if parent[u] else 0

        for v in adj[u]:
            if v == parent[u]:
                continue
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)
            elif not found_cycle:
                # Back edge found - u -> v where v is ancestor
                if v != parent[u] and depth[v] < depth[u]:
                    cycle_len = depth[u] - depth[v]
                    # Build cycle path from u back to v
                    path = []
                    curr = u
                    while curr != v:
                        path.append(curr)
                        curr = parent[curr]
                    path.append(v)
                    cycle_nodes = path

                    if cycle_len < target:
                        # This cycle is too short, but keep exploring for longer ones
                        pass
                    else:
                        found_cycle = True
                        break
        if found_cycle:
            break

    if found_cycle:
        return f"2\n{len(cycle_nodes)}\n{' '.join(map(str, cycle_nodes))}\n"
    else:
        # Find independent set using odd-depth nodes in DFS tree
        odd_depth_nodes = []
        for i in range(1, n + 1):
            if visited[i] and depth[i] % 2 == 1:
                odd_depth_nodes.append(i)

        # Fallback: all same-depth nodes are independent
        nodes_per_level = {}
        for i in range(1, n + 1):
            if visited[i]:
                if depth[i] not in nodes_per_level:
                    nodes_per_level[depth[i]] = []
                nodes_per_level[depth[i]].append(i)

        for level, nodes in nodes_per_level.items():
            if len(nodes) >= target:
                return f"1\n{' '.join(map(str, nodes))}\n"

        # Final fallback: odd depth nodes
        if len(odd_depth_nodes) >= target:
            return f"1\n{' '.join(map(str, odd_depth_nodes))}\n"

        # Should not reach here for connected graphs
        return f"1\n{' '.join(map(str, odd_depth_nodes))}\n"

