def get_divisors(num):
    """Get divisors of num except 1 (since we need GCD > 1)"""
    divs = set()
    if num == 1:
        return divs
    i = 2
    while i * i <= num:
        if num % i == 0:
            divs.add(i)
            divs.add(num // i)
        i += 1
    return divs

