class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.n = len(s)
        self.MOD = 10**9 + 7

    def number(self):
        """Parse a positive integer (one or more digits)"""
        start = self.pos
        while self.pos < self.n and self.s[self.pos].isdigit():
            self.pos += 1
        if start < self.pos:
            return int(self.s[start:self.pos])
        return None

    def parse_term(self):
        """Parse a term: number | number-'-' number | number '(' expression ')'"""
        num1 = self.number()
        if num1 is None:
            raise ValueError("Expected number")

        if self.pos >= self.n:
            # Plain number
            return num1

        c = self.peek()

        if c == '-':
            # Range: num1-num2
            self.pos += 1
            num2 = self.number()
            return self.eval_range(num1, num2)

        if c == '(':
            # Repetition: num1(expression)
            self.pos += 1
            expr_result = self.parse_expression()
            self.pos += 1  # skip ')'
            return self.eval_repeat(num1, expr_result)

        return num1

    def peek(self):
        """Look at current char without consuming"""
        if self.pos < self.n:
            return self.s[self.pos]
        return None

    def parse_expression(self):
        """Parse an expression: term | term '+' term"""
        result = self.parse_term()

        while self.pos < self.n and self.s[self.pos] == '+':
            self.pos += 1
            right = self.parse_term()
            result = self.concat(result, right)

        return result

    def eval_range(self, l, r):
        """Concatenate all integers from l to r"""
        value = 0
        digits = 0

        for i in range(l, r + 1):
            s = str(i)
            d = len(s)
            value = (value * (10 ** d) + i) % self.MOD
            digits += d

        return {'val': value, 'digits': digits}

    def eval_repeat(self, n, expr):
        """Repeat expression n times (concatenation)"""
        val = expr['val']
        digits = expr['digits']

        # val is already modded
        # Repeating n times: val * 10^(digits*n) + ... + val
        total_digits = digits * n

        # Result = val * (10^((total_digits - digits) + digits*n - digits) + val)
        # Actually simpler: n copies concatenated
        # Each copy has 'digits' places

        result = 0
        power = total_digits - digits  # Multiplier for first copy
        current_power = power
        n_left = 1

        for _ in range(n):
            if _ < n - 1:
                # Combine with next copy
                current_power -= digits  # Make room
                result = (result * (10 ** digits) + val) % self.MOD
            else:
                result = (result * (10 ** digits) + val) % self.MOD

        return {'val': result, 'digits': digits * n}

    def concat(self, left, right):
        """Concatenate two values"""
        val1 = left
        d2 = right['digits']
        val2 = right['val']
        return (val1 * (10 ** d2) + val2) % self.MOD

    def parse(self):
        """Parse and evaluate the entire expression"""
        return self.parse_expression()


